/**
 * The board's `<head>` and the icon files it points at (#723).
 *
 * The icon set is generated by `scripts/build-icons.mjs`, which needs a browser
 * and so cannot run in CI. This spec therefore checks the committed artefacts
 * and the head that names them, never the generator: a link pointing at a file
 * nobody shipped, or a `favicon.ico` regenerated to the wrong sizes, fails here
 * without a chromium anywhere.
 *
 * The bytes are read as bytes on purpose. `favicon.ico` served as `text/html`
 * is the bug this issue fixes, and a test that only checked the path existed
 * would have passed against it.
 */
// @ts-expect-error node:fs is untyped here; it exists in vitest's node env.
import { readFileSync, existsSync } from 'node:fs';
import { describe, expect, it } from 'vitest';

const INDEX = new URL('../index.html', import.meta.url);
const PUBLIC = new URL('../public/', import.meta.url);

const html: string = readFileSync(INDEX, 'utf8');

/** Every `<link>` in the file, as its rel tokens and its href. */
const links: { rels: string[]; href: string }[] = (html.match(/<link\b[^>]*>/g) ?? []).map(
  (tag) => ({
    rels: (tag.match(/\brel="([^"]*)"/)?.[1] ?? '').split(/\s+/).filter(Boolean),
    href: tag.match(/\bhref="([^"]*)"/)?.[1] ?? '',
  }),
);

/** The href of the first `<link>` whose rel tokens are exactly this rel. */
function linkHref(rel: string): string | undefined {
  const want = rel.split(/\s+/);
  const hit = links.find(
    (l) => l.rels.length === want.length && want.every((r) => l.rels.includes(r)),
  );
  return hit?.href;
}

/** Resolve a root-absolute href to the file vite would copy out of public/. */
function publicFile(href: string): URL {
  return new URL(href.replace(/^\//, ''), PUBLIC);
}

function publicBytes(name: string): Uint8Array {
  return new Uint8Array(readFileSync(new URL(name, PUBLIC)));
}

describe('index.html declares the board mark', () => {
  it('links an SVG icon that exists in public/', () => {
    const svg = links.find((l) => l.rels.includes('icon') && l.href.endsWith('.svg'));
    expect(svg, 'no rel="icon" <link> points at an SVG').toBeTruthy();
    expect(existsSync(publicFile(svg!.href))).toBe(true);
  });

  it('links an apple-touch-icon that exists in public/', () => {
    const href = linkHref('apple-touch-icon');
    expect(href).toBeTruthy();
    expect(existsSync(publicFile(href!))).toBe(true);
  });

  it('links a Safari mask-icon that exists in public/', () => {
    const href = linkHref('mask-icon');
    expect(href).toBeTruthy();
    expect(existsSync(publicFile(href!))).toBe(true);
  });

  it('links the legacy /favicon.ico from an icon rel', () => {
    const ico = links.find((l) => l.href === '/favicon.ico');
    expect(ico, 'no <link> points at /favicon.ico').toBeTruthy();
    expect(ico!.rels).toContain('icon');
    expect(existsSync(publicFile(ico!.href))).toBe(true);
  });

  it('does not still call the board a Hypothesis Cycle', () => {
    const title = html.match(/<title>([^<]*)<\/title>/)?.[1];
    expect(title).toBeTruthy();
    expect(title).not.toContain('Hypothesis');
  });
});

describe('the generated icon files', () => {
  it('favicon.ico is an ICO carrying at least the 16 and 32 sizes', () => {
    const ico = publicBytes('favicon.ico');
    // ICO magic: reserved=0, type=1 (icon), both little-endian 16-bit.
    expect(Array.from(ico.slice(0, 4))).toEqual([0x00, 0x00, 0x01, 0x00]);

    const count = ico[4] | (ico[5] << 8);
    expect(count).toBeGreaterThanOrEqual(2);

    // Each 16-byte directory entry opens with its width; 0 means 256.
    const widths: number[] = [];
    for (let i = 0; i < count; i++) {
      const w = ico[6 + i * 16];
      widths.push(w === 0 ? 256 : w);
    }
    expect(widths).toContain(16);
    expect(widths).toContain(32);
  });

  it('apple-touch-icon.png is a 180x180 PNG', () => {
    const png = publicBytes('apple-touch-icon.png');
    expect(Array.from(png.slice(0, 8))).toEqual([
      0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
    ]);
    // IHDR is the first chunk: width and height are big-endian at 16 and 20.
    const view = new DataView(png.buffer, png.byteOffset, png.byteLength);
    expect(view.getUint32(16)).toBe(180);
    expect(view.getUint32(20)).toBe(180);
  });

  it('apple-touch-icon.png carries no alpha channel', () => {
    // iOS does not honour alpha in a home-screen icon: it composites onto black,
    // so a disc on transparency lands as a blue circle in a black square while
    // every neighbouring app icon is full-bleed. The generator therefore paints
    // the mark's ground behind it and writes this one file without an alpha
    // channel. IHDR's colour type is byte 25: 2 is truecolour, 6 is truecolour
    // with alpha. The ICO entries keep their alpha and are checked above — a tab
    // favicon composites onto the tab, where a square would be wrong.
    const png = publicBytes('apple-touch-icon.png');
    expect(png[25]).toBe(2);
  });
});
